import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Prose","description":"","frontmatter":{},"headers":[],"relativePath":"components/prose.md","filePath":"components/prose.md"}'),s={name:"components/prose.md"};function n(i,e,h,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="prose" tabindex="-1">Prose <a class="header-anchor" href="#prose" aria-label="Permalink to &quot;Prose&quot;">​</a></h1><p>Prose is a container for text meant to be read: help, terms, tutorials.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for long text written as plain HTML: headings h1 to h4, paragraphs, lists, terms and descriptions, code, quotations, figures, tables and folded parts. Prose styles the elements; the content needs no classes. Short text in the interface is a <a href="./text">Text</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>children</code></td><td>required</td><td>The content, plain HTML</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The width is at most <code>--kata-width-prose</code> and the text takes the prose role, one quarter step larger than interface text. Prose is the one component whose children have outer margins, in em: pad-lg before each block, pad-xl before an h2, and after a heading the heading&#39;s offset, so that a heading sits closer to the text it introduces. The headings take the roles title, h1, h2 and label. Code is one quarter step smaller than the text around it, links in running text are underlined and a wide table scrolls sideways. The anchor of a heading, a link marked <code>data-role=&quot;heading-anchor&quot;</code> inside it, shows only while the heading is hovered or holds the focus.</p><p>The summary of a folded part is body text at the label weight after a chevron of the icon size, which turns down when the part is open. The chevron is centred on the ink of the summary&#39;s first line, so a summary that wraps keeps it there (<a href="./../measuring#a-mark-beside-text">a mark beside text</a>).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/prose/" title="Prose" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/prose/" target="_blank" rel="noopener">Prose</a></figcaption></figure>',11)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
